{
  "service": "mock-api",
  "description": "mock-api edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8081
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 8503,
      "weight": 3,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 7594,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 8400,
      "weight": 4,
      "health_check": "/healthz"
    },
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 8788,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 9259,
      "weight": 6,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/catalog/tokens",
      "upstream": "catalog",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 3000,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/items",
      "upstream": "accounts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2000,
      "retries": 3
    },
    {
      "path": "/api/v1/shipping/items",
      "upstream": "shipping",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 1
    },
    {
      "path": "/api/v1/shipping/batch",
      "upstream": "shipping",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2000,
      "retries": 0
    },
    {
      "path": "/api/v1/inventory/history",
      "upstream": "inventory",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 3
    },
    {
      "path": "/api/v1/accounts/export",
      "upstream": "accounts",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 1
    }
  ]
}

